// Dense heap-style arrays can use:
// left(i)  = 2 * i + 1
// right(i) = 2 * i + 2`}],algorithms:[{title:"Find every leaf",label:"Base case recognition",summary:"A leaf is detected locally: the node exists and has no left or right child. Once found, record it and stop descending that path. Do not confuse a node with one missing child for a leaf.",invariant:"Every completed recursive call returns all and only the leaves in that node’s subtree, from left to right.",useWhen:"Collecting boundaries, comparing leaf sequences, pruning, summing terminal paths, or defining recursion base cases.",example:["Visit 8 → recurse","Visit 3 → recurse","1 is a leaf → collect","6 is a leaf → collect","9 and 14 are leaves → collect","Result: [1, 6, 9, 14]"],code:`function collectLeaves(root: TreeNode | null): number[] {
